def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "clear_plates": And([
            self.dessert_served(),
            Not(self.guest_accepted_seconds()),
            self.schedule_flexible,
            Not(self.lingering_mode)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
